    MA([("kinderdagverblijf","creche"),("bso","ATL"),("gastouder","ama"),("kinderopvang","acolhimento de crianças")], "Acolhimento.", ["v-kinderdagverblijf","v-bso","v-gastouder","v-kinderopvang"]),
    AR("kinderdagverblijf","a creche","het", "Het verblijf.", ["v-kinderdagverblijf"]),
    CO("text","Kinderopvang in Nederland", "Veel ouders in Nederland werken allebei, vaak in deeltijd. Voor kinderen tot vier jaar is er het kinderdagverblijf of een gastouder. Vanaf vier jaar gaan kinderen naar de basisschool. Na schooltijd kunnen ze naar de buitenschoolse opvang (bso). Kinderopvang is niet goedkoop, maar werkende ouders kunnen een toeslag van de overheid krijgen.",
       [("Até que idade se vai à creche?", ["*Até aos quatro anos","Até aos seis","Até aos dois"]),("O que é a bso?", ["*Acolhimento depois da escola","Uma escola de línguas","Um desporto"]),("Que ajuda existe?", ["*Um subsídio do governo para pais que trabalham","Nenhuma","Creche grátis para todos"])],
       "Sistema geral (regras de subsídio mudam).", ["v-kinderdagverblijf","v-bso","v-kinderopvang"]),
