L(22, "Debate: fardas escolares?", "Moeten scholieren een uniform dragen?",
  ["Debater um tema de educação com argumentos"],
  vocab=[V("v-schooluniform","schooluniform","farda escolar","noun","het"), V("v-gelijkheid","gelijkheid","igualdade","noun","de"),
         V("v-individualiteit","individualiteit","individualidade","noun","de"), V("v-merkkleding","merkkleding","roupa de marca","noun","de")],
  ex=[("In Nederland dragen scholieren meestal geen schooluniform.","Nos Países Baixos os alunos normalmente não usam farda."),("Een uniform zorgt voor meer gelijkheid.","Uma farda traz mais igualdade."),("Kleding is ook een uiting van individualiteit.","A roupa também é uma expressão da individualidade."),("Sommige kinderen worden gepest om hun merkkleding.","Algumas crianças sofrem bullying por causa da roupa de marca.")],
  review=["v-naar-mijn-mening","v-aan-de-andere-kant","v-pesten"],
  cefr=C, exs=[
    MA([("schooluniform","farda escolar"),("gelijkheid","igualdade"),("individualiteit","individualidade"),("merkkleding","roupa de marca")], "Debate.", ["v-schooluniform","v-gelijkheid","v-individualiteit","v-merkkleding"]),
    AR("schooluniform","a farda escolar","het", "Het uniform.", ["v-schooluniform"]),
    CO("text","Twee meningen", "Sanne (lerares): «Ik ben voor een schooluniform. Dan zie je geen verschil meer tussen rijke en arme kinderen, en niemand wordt gepest om zijn merkkleding. Het zorgt voor meer gelijkheid.»\nBram (scholier): «Ik ben ertegen. Met kleding laat je zien wie je bent. Een uniform past niet bij de Nederlandse cultuur, waar individualiteit belangrijk is. Bovendien zijn uniformen duur voor ouders.»",
       [("Qual é o argumento principal da Sanne?", ["*Mais igualdade e menos bullying","São bonitas","São baratas"]),("O que diz o Bram sobre a roupa?", ["*Mostra quem és","É cara","Não é importante"]),("Que argumento prático usa o Bram?", ["*As fardas são caras para os pais","São desconfortáveis","São feias"])],
       "Duas opiniões.", ["v-schooluniform","v-gelijkheid","v-individualiteit","v-merkkleding"]),
    TR("pt-nl","Uma farda traz mais igualdade.", ["Een uniform zorgt voor meer gelijkheid","Een schooluniform zorgt voor meer gelijkheid"], "zorgen voor.", ["v-gelijkheid"]),
    TR("pt-nl","Sou contra as fardas.", ["Ik ben tegen schooluniformen","Ik ben tegen uniformen","Ik ben tegen een schooluniform"], "tegen zijn.", ["v-schooluniform"]),
    MC("Em Portugal, nas escolas públicas, a farda é…", ["*pouco comum (mais em colégios privados)","obrigatória em todas|Não.","proibida|Não."], "Comparação.", ["v-schooluniform"]),
    FE(["Een","uniform","zorgen","voor","gelijkheid."], 2, "zorgt", "Singular: zorgt.", ["v-gelijkheid"]),
    FB("Kleding is een uiting van ___.", ["individualiteit"], "Individualidade.", ["v-individualiteit"], choices=["individualiteit","gelijkheid","uniform"], tr="A roupa é uma expressão de individualidade."),
    LI("Aan de andere kant zijn uniformen duur voor ouders.", ["Aan de andere kant zijn uniformen duur voor ouders"], "Por outro lado, as fardas são caras para os pais.", "Contra-argumento.", ["v-aan-de-andere-kant"]),
    SW("Dê a sua opinião sobre fardas escolares (5–6 frases), com dois argumentos e um contra-argumento.", ["Naar mijn mening is een schooluniform een goed idee. Ten eerste zorgt het voor meer gelijkheid tussen leerlingen. Bovendien hoeven ouders minder geld uit te geven aan merkkleding. Aan de andere kant is kleding een manier om je individualiteit te laten zien. Toch denk ik dat de voordelen groter zijn. Kortom: ik ben voor een eenvoudig uniform."], ["Opinião", "Dois argumentos", "Contra-argumento", "Conclusão"], 55, "Opinião.", ["v-schooluniform","v-gelijkheid"]),
  ], diff=4, mins=7)

